"""Check native inputs, full-body inverse balance, and the encoded V4 release."""
from pathlib import Path
import hashlib,sys
import numpy as np,imageio_ffmpeg
from PIL import Image
from jump_monitor_data import ROOT,read,atomic
from compose_jump_rl_draft_v4 import Draft,BG
OUT=ROOT/'deliverables/jump_rl_study_draft_v4'

def main():
    m=read(OUT/'source_manifest.json');a=read(OUT/'muscle_analysis.json');compat=read(OUT/'training_compatibility.json');prefix=read(OUT/'prefix_check.json');metrics=read(OUT/'metrics.json');checks=[]
    assert compat['passed'] and compat['qpos_max_error']<1e-10
    assert prefix['max_pixel_error']==0
    for key in m['final_four_keys']:
        assert metrics['cases'][key]['torque_limits_all_Nm']==metrics['cases']['initial']['torque_limits_all_Nm'] and metrics['cases'][key]['max_torque_cap_ratio']<=1.00001
        c=next(c for c in m['cases']if c['key']==key);f=Path(c['multiview_folder']);z=np.load(f/'muscles.npz');source=np.load(Path(c['folder'])/'motion.npz');assert np.array_equal(source['qpos'],np.load(f/'motion.npz')['qpos']);r=a['cases'][key]
        error=float(abs(np.einsum('tqn,tn->tq',z['R'],z['all_force_N'])-z['target']).max());floor=float(np.max(z['passive_force_N']-z['all_force_N']));assert error<.01 and floor<1e-5 and np.min(z['all_force_N'])>=-1e-5
        assert z['R'].shape[1:]==(21,442) and r['muscle_count']==438
        for field,tol in [('NE_crosscheck_max_SI',1e-5),('position_error_m',1e-9),('girdle_rigid_registration_error',1e-8),('girdle_unit_wrench_closure',1e-7),('scapular_contact_gap_max',1e-8)]:assert r[field]<tol,(key,field)
        mapping=read(f/'fullbody_contour_mapping.json');assert mapping['color_stops_N']==[0,100,1000,30000] and mapping['palette_is_common_to_all_candidates'] and mapping['unknown_is_not_zero'] and not mapping['force_values_changed'];assert mapping['mapped_surfaces']>150
        for name in [c['multiview_dir'],c['full_side_dir']]:assert len(list((f/name).glob('frame_*.png')))==round(c['duration_s']*24)+1
        checks.append(dict(key=key,muscle_paths=438,balance_rows=21,moment_balance_max_error_Nm=error,passive_floor_violation_N=max(0.,floor),source_qpos_identical=True,mapped_surfaces=mapping['mapped_surfaces'],unidentified_surfaces=len(mapping['unidentified_surfaces']),position_error_m=r['position_error_m']))
    extension=read(ROOT/'deliverables/jump_landing_live/range_expansion_status.json');assert extension['fixed_torque_capacities'] and extension['goal_retained_m']==3. and len(extension['bounds'])==58
    for b in extension['bounds']:assert b['expanded'][0]<=b['previous'][0]+1e-10 and b['expanded'][1]>=b['previous'][1]-1e-10
    camera=read(OUT/'camera_border_check.json');assert camera['sampled_images']==32 and not camera['border_touches']
    qa=dict(passed=True,cases=checks,prefix=prefix,camera_border_check=camera,training_compatibility=compat,conditional_inverse_forces=True,human_muscle_force_validation=False,physical_caps_unchanged=True,expanded_parameter_count=58,search_target_retained_m=3.,final_four_phase_aligned=True,body_colors='Common absolute N logarithmic scale',curve_cards='Right-side group / initial successful push-off peak',unsupported_surfaces='N/A; not zero')
    atomic(OUT/'source_check.json',qa)
    if '--sources-only'in sys.argv:print('V4_SOURCES_PASS',flush=True);return
    d=read(OUT/'draft_delivery.json');draft=Draft();reader=imageio_ffmpeg.read_frames(d['video'],pix_fmt='rgb24');meta=next(reader);assert tuple(meta['size'])==(1080,1920) and meta['fps']==30;count=0;footer=0
    targets={round(36.2*30):'trajectory',round((draft.duration-3.5)*30):'four_simultaneous'}
    for raw in reader:
        im=np.frombuffer(raw,dtype=np.uint8).reshape(1920,1080,3);footer=max(footer,int(abs(im[1536:].astype(int)-np.array(BG)).max()))
        if count in targets:Image.fromarray(im).save(OUT/f'encoded_{targets[count]}.png')
        count+=1
    assert count==d['frames'] and footer<=4,(count,footer)
    qa.update(frames=count,duration_s=count/30,resolution=[1080,1920],footer_blank_px=384,encoded_footer_max_rgb_error=footer,video_sha256=hashlib.sha256(Path(d['video']).read_bytes()).hexdigest());atomic(OUT/'delivery_check.json',qa)
    cap=metrics['cases']['initial']['joint_limits_Nm'][2];initial=metrics['cases']['initial']['peak_push']['ankle'];best=metrics['cases']['best_checked']['peak_push']['ankle'];usage=dict(joint='right ankle',fixed_cap_Nm=cap,initial_push_peak_Nm=initial,best_checked_push_peak_Nm=best,initial_fraction=initial/cap,best_fraction=best/cap,source='metrics.json: native push-off torque peaks',meaning='Same net joint cap; actual torque utilization changes. Muscle force also depends on moment arms, passive tension and conditional force sharing.');atomic(OUT/'torque_usage.json',usage)
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jump study · V4</title><style>body{margin:0;background:#0c1827;color:#e9eff5;font:17px/1.7 system-ui}main{max-width:1100px;margin:auto;padding:24px}h1{font-size:28px}h2{font-size:21px}a{color:#77dac7}.grid{display:grid;grid-template-columns:440px 1fr;gap:28px}video{width:100%;max-height:86vh;border-radius:14px}.card{background:#142438;padding:18px;border-radius:12px}small{color:#a8bdce}@media(max-width:780px){.grid{display:block}}</style><main><h1>Same limits. Better coordination.</h1><p>V4 · DURATION s · approved first 33 s preserved</p><div class="grid"><div><video controls playsinline preload="metadata" poster="/rl_draft_v4/preview_trajectory.png" src="/rl_draft_v4.mp4"></video><p><a href="/rl_draft_v4.mp4" download>Download MP4</a> · <a href="/rl_draft_v3.html">V3</a></p></div><div><div class="card"><b>Stable landing beyond 3 m</b><p id="live">Loading…</p><a href="/landing_live.html">Live learning and motion</a></div><h2>Three views, one motion</h2><p>After 33 s: synchronized front-oblique, rear-oblique and fixed-world side views. The airborne centre-of-mass trajectory is revealed after touchdown. LOAD / PUSH / AIR / LAND remain. Four candidates finish together in a matched front-oblique view from above; their phases are aligned for comparison, without changing the underlying simulations.</p><h2>Same cap, more muscle tension?</h2><p>Partly. The right ankle push-off torque rises from about 261 to 368 Nm, using 56% → 79% of its unchanged 468 Nm cap. Timing and posture can improve useful torque delivery. But muscle tension also depends on moment arms, passive tension and force sharing: not every muscle must increase. The cap constrains net joint torque, not each muscle's force.</p></div></div><h2>Whole-body tension</h2><p>438 model muscle paths are solved in a separate inverse analysis of the unchanged motion. Eleven net joint torque balances plus ten analysis-only shoulder-girdle support balances and four compressive scapulothoracic normals account for arm/back support. The forward learner still uses joint torques; these forces do not feed back into learning.</p><p><b>Body colors:</b> common absolute tension scale, logarithmic 0–30 kN, across all candidates. Surface values sum the explicitly mapped model paths. Grey N/A surfaces have no identified force in this model; grey does not mean zero. This covers the represented major whole-body muscles, not every anatomical muscle.</p><p><b>Four curve cards:</b> right-side muscle-group tension divided by that group's initial successful push-off peak. 1.0× is a reference, not 100% strength. The contour and curve scales differ deliberately: absolute whole-body location versus relative group comparison.</p><p>The nonnegative allocation minimizes normalized force magnitude and temporal variation, retaining native passive floors. Added girdle passive forces are unidentified; no muscle strength ceiling is imposed. Numerical equilibrium and identical source poses are checked. These are conditional model forces, not measured individual forces, EMG, fatigue or physiological activation.</p><h2>Search range</h2><p>The 58 posture, timing and drive variables now have wider search bounds; body mass, inertia, joint motion limits, contact and final torque caps remain unchanged. Target: at least 3.00 m retained after stable landing. Head recentering is logged separately from PPO updates. Longer falling attempts are retained. The four video candidates are a frozen checked snapshot: 2.19 / 2.46 / 2.60 / 2.74 m; the active search continues separately.</p><h2>Evidence and credits</h2><p><a href="/rl_draft_v4/delivery_check.json">Release checks</a> · <a href="/rl_draft_v4/muscle_analysis.json">438-path inverse analysis</a> · <a href="/rl_draft_v4/torque_usage.json">Torque utilization</a> · <a href="/rl_draft_v4/metrics.json">Native metrics</a> · <a href="/rl_draft_v4/parameter_catalogue.json">58 parameters</a> · <a href="/rl_draft_v4/ANATOMY_CREDITS.md">Model credits</a></p><small>MuJoCo · PPO · MyoSuite/MyoHub · BodyParts3D © DBCLS · Z-Anatomy/BodyExplorer. Standard anthropometry; sagittal reduced rigid-body model. 1080 × 1920, 30 fps, bottom 384 px blank.</small></main><script>async function live(){try{let s=await(await fetch('/landing_live/status.json',{cache:'no-store'})).json();document.getElementById('live').textContent=`${s.status} · ${s.training_episodes} trials · ${s.policy_updates} PPO updates · checked ${s.verified?.min_fine_retained_m?.toFixed(2)??'—'} m · target ${s.target_retained_m?.toFixed(2)??'3.00'} m`;}catch(e){}}live();setInterval(live,5000);</script></html>'''
    (OUT/'index.html').write_text(html.replace('DURATION',f'{count/30:.1f}'),encoding='utf-8')
    statefile=ROOT/'docs/standing_long_jump_working_state.json';state=read(statefile);state['latest_video_draft']=dict(version=4,folder=str(OUT),video=d['video'],duration_s=count/30,preserved_prefix_s=33,visible_parameter_outputs=58,torque_channels=11,final_views=m['final_views'],final_four_simultaneous=True,conditional_muscle_tension=True,muscle_paths=438,forward_training_still_torque_driven=True,last_candidate_replaceable=True);state['muscle_postprocessing']=dict(script='scripts/build_fullbody_jump_muscles_v4.py',result_folder=str(OUT),feeds_back_to_training=False,selection='Normalized nonnegative force magnitude and continuity, passive floors, no strength cap',body_colors='Common absolute N logarithmic scale; unsupported surfaces N/A',curves='Four right-side groups / initial group push-off peak');state['latest_three_metre_search']=dict(audit=str(ROOT/'deliverables/jump_landing_live/range_expansion_status.json'),target_retained_m=3.,target_first_m=3.1,fixed_torque_caps=True,training_continues=True);atomic(statefile,state)
    print('V4_PACKAGE_PASS',count,footer,flush=True)

if __name__=='__main__':main()
